function(){
  var labels=['抖音热榜'];
  var visible=function(el){return !!el&&!!(el.offsetWidth||el.offsetHeight||el.getClientRects().length);};
  var target=Array.from(document.querySelectorAll('button,[role="button"],a,span,div'))
    .find(function(el){return visible(el)&&labels.indexOf((el.innerText||'').trim())>=0;});
  if(target){try{target.click();return true;}catch(e){return false;}}
  return false;
}

function(ctx){
  var keywords=['热','榜','话题','挑战','同城','推荐','音乐','剧情','搞笑','美食','穿搭','旅行','开箱','测评'];
  var selectors=['[data-e2e="feed-right-list-container"] li'];
  var limit=Number(ctx.limit)||20;
  var out=[];var seen={};
  for(var s=0;s<selectors.length;s++){
    var nodes=Array.from(document.querySelectorAll(selectors[s])).slice(0,600);
    for(var i=0;i<nodes.length&&out.length<limit;i++){
      var txt=(nodes[i].innerText||'').trim();
      if(!txt)continue;
      var lines=txt.split(/\n/).map(function(x){return x.trim();}).filter(Boolean);
      var heat=lines.find(function(x){return /^\d+(\.\d+)?[万亿]?热度$/.test(x);})||'';
      var hasKeyword=keywords.some(function(k){return txt.indexOf(k)>=0;});
      if(!heat&&!(hasKeyword&&lines.length>=2))continue;
      var name=lines.find(function(x){
        return x!=='抖音热榜'&&!/^\d{1,3}$/.test(x)&&!/^\d+(\.\d+)?[万亿]?热度$/.test(x)
          &&x.length>=2&&x.length<=80;
      })||'';
      if(!name||seen[name])continue;
      seen[name]=1;
      out.push({rank:out.length+1,title:name,heat:heat,summary:txt.slice(0,200)});
    }
    if(out.length)break;
  }
  return {count:out.length,topics:out,url:location.href};
}
